package store

var qRetainBatchInputReceipts = statement{sqlite: `DELETE FROM input_receipts WHERE (watch_id,generation,input_id) IN (SELECT watch_id,generation,input_id FROM input_receipts WHERE expires_at<=? ORDER BY expires_at LIMIT ?)`, postgres: `DELETE FROM input_receipts WHERE workspace_id=current_setting('ding.workspace') AND (watch_id,generation,input_id) IN (SELECT watch_id,generation,input_id FROM input_receipts WHERE workspace_id=current_setting('ding.workspace') AND expires_at<= $1 ORDER BY expires_at LIMIT $2)`}

var qRetainBatchPushReceipts = statement{sqlite: `DELETE FROM push_receipts WHERE (lifetime,producer,input_key) IN (SELECT lifetime,producer,input_key FROM push_receipts WHERE expires_at<=? ORDER BY expires_at LIMIT ?)`, postgres: `DELETE FROM push_receipts WHERE workspace_id=current_setting('ding.workspace') AND (lifetime,producer,input_key) IN (SELECT lifetime,producer,input_key FROM push_receipts WHERE workspace_id=current_setting('ding.workspace') AND expires_at<= $1 ORDER BY expires_at LIMIT $2)`}

var qRetainBatchBackoff = statement{sqlite: `DELETE FROM metadata WHERE key IN (SELECT key FROM metadata WHERE key LIKE 'delivery_backoff:%' AND CAST(value AS INTEGER)<=? ORDER BY key LIMIT ?)`, postgres: `DELETE FROM metadata WHERE workspace_id=current_setting('ding.workspace') AND key IN (SELECT key FROM metadata WHERE workspace_id=current_setting('ding.workspace') AND key LIKE 'delivery_backoff:%' AND CASE WHEN key LIKE 'delivery_backoff:%' THEN CAST(value AS BIGINT) ELSE 0 END<=$1 ORDER BY key LIMIT $2)`}

var qRetainBatchOutbox = statement{sqlite: `DELETE FROM outbox WHERE id IN (SELECT id FROM outbox WHERE created_at<? AND status NOT IN ('pending','leased') ORDER BY created_at,id LIMIT ?)`, postgres: `DELETE FROM outbox WHERE workspace_id=current_setting('ding.workspace') AND id IN (SELECT id FROM outbox WHERE workspace_id=current_setting('ding.workspace') AND created_at<$1 AND status NOT IN ('pending','leased') ORDER BY created_at,id LIMIT $2)`}

var qRetainBatchEvents = statement{sqlite: `DELETE FROM events WHERE id IN (SELECT id FROM events WHERE at<? AND NOT EXISTS(SELECT 1 FROM outbox WHERE event_id=events.id) AND NOT EXISTS(SELECT 1 FROM entity_pins WHERE kind='event' AND value=events.id) ORDER BY at,sequence LIMIT ?)`, postgres: `DELETE FROM events WHERE workspace_id=current_setting('ding.workspace') AND id IN (SELECT id FROM events WHERE workspace_id=current_setting('ding.workspace') AND at<$1 AND NOT EXISTS(SELECT 1 FROM outbox WHERE workspace_id=current_setting('ding.workspace') AND event_id=events.id) AND NOT EXISTS(SELECT 1 FROM entity_pins WHERE workspace_id=current_setting('ding.workspace') AND kind='event' AND value=events.id) ORDER BY at,sequence LIMIT $2)`}

var qRetainBatchObservations = statement{sqlite: `DELETE FROM observations WHERE sequence IN (SELECT sequence FROM observations WHERE accepted_at<? AND NOT EXISTS(SELECT 1 FROM event_evidence WHERE observation_sequence=observations.sequence) AND NOT EXISTS(SELECT 1 FROM entity_pins WHERE kind='input' AND value=CAST(observations.sequence AS TEXT)) ORDER BY accepted_at,sequence LIMIT ?)`, postgres: `DELETE FROM observations WHERE workspace_id=current_setting('ding.workspace') AND sequence IN (SELECT sequence FROM observations WHERE workspace_id=current_setting('ding.workspace') AND accepted_at<$1 AND NOT EXISTS(SELECT 1 FROM event_evidence WHERE workspace_id=current_setting('ding.workspace') AND observation_sequence=observations.sequence) AND NOT EXISTS(SELECT 1 FROM entity_pins WHERE workspace_id=current_setting('ding.workspace') AND kind='input' AND value=CAST(observations.sequence AS TEXT)) ORDER BY accepted_at,sequence LIMIT $2)`}

var qRetainBatchWatches = statement{sqlite: `DELETE FROM watches WHERE id IN (SELECT id FROM watches WHERE status='deleted' AND next_at<? AND NOT EXISTS (SELECT 1 FROM entities WHERE watch_id=watches.id) AND NOT EXISTS (SELECT 1 FROM observations WHERE watch_id=watches.id) AND NOT EXISTS (SELECT 1 FROM events WHERE watch_id=watches.id) AND NOT EXISTS (SELECT 1 FROM outbox WHERE watch_id=watches.id) AND NOT EXISTS (SELECT 1 FROM timers WHERE watch_id=watches.id) AND NOT EXISTS (SELECT 1 FROM input_receipts WHERE watch_id=watches.id) ORDER BY next_at,id LIMIT ?)`, postgres: `DELETE FROM watches WHERE workspace_id=current_setting('ding.workspace') AND id IN (SELECT id FROM watches WHERE workspace_id=current_setting('ding.workspace') AND status='deleted' AND next_at<$1 AND NOT EXISTS (SELECT 1 FROM entities WHERE workspace_id=current_setting('ding.workspace') AND watch_id=watches.id) AND NOT EXISTS (SELECT 1 FROM observations WHERE workspace_id=current_setting('ding.workspace') AND watch_id=watches.id) AND NOT EXISTS (SELECT 1 FROM events WHERE workspace_id=current_setting('ding.workspace') AND watch_id=watches.id) AND NOT EXISTS (SELECT 1 FROM outbox WHERE workspace_id=current_setting('ding.workspace') AND watch_id=watches.id) AND NOT EXISTS (SELECT 1 FROM timers WHERE workspace_id=current_setting('ding.workspace') AND watch_id=watches.id) AND NOT EXISTS (SELECT 1 FROM input_receipts WHERE workspace_id=current_setting('ding.workspace') AND watch_id=watches.id) ORDER BY next_at,id LIMIT $2)`}

var qRetainBatchWatchRevisions = statement{sqlite: `DELETE FROM watch_revisions WHERE (watch_id,revision) IN (SELECT watch_id,revision FROM watch_revisions WHERE created_at<? AND NOT EXISTS (SELECT 1 FROM watches WHERE id=watch_id AND watches.revision=watch_revisions.revision) AND NOT EXISTS (SELECT 1 FROM entities WHERE entities.watch_id=watch_revisions.watch_id AND entities.revision=watch_revisions.revision) AND NOT EXISTS (SELECT 1 FROM observations WHERE observations.watch_id=watch_revisions.watch_id AND observations.revision=watch_revisions.revision) AND NOT EXISTS (SELECT 1 FROM events WHERE events.watch_id=watch_revisions.watch_id AND events.revision=watch_revisions.revision) ORDER BY created_at,watch_id,revision LIMIT ?)`, postgres: `DELETE FROM watch_revisions WHERE workspace_id=current_setting('ding.workspace') AND (watch_id,revision) IN (SELECT watch_id,revision FROM watch_revisions WHERE workspace_id=current_setting('ding.workspace') AND created_at<$1 AND NOT EXISTS (SELECT 1 FROM watches WHERE workspace_id=current_setting('ding.workspace') AND id=watch_id AND watches.revision=watch_revisions.revision) AND NOT EXISTS (SELECT 1 FROM entities WHERE workspace_id=current_setting('ding.workspace') AND entities.watch_id=watch_revisions.watch_id AND entities.revision=watch_revisions.revision) AND NOT EXISTS (SELECT 1 FROM observations WHERE workspace_id=current_setting('ding.workspace') AND observations.watch_id=watch_revisions.watch_id AND observations.revision=watch_revisions.revision) AND NOT EXISTS (SELECT 1 FROM events WHERE workspace_id=current_setting('ding.workspace') AND events.watch_id=watch_revisions.watch_id AND events.revision=watch_revisions.revision) ORDER BY created_at,watch_id,revision LIMIT $2)`}

var qRetainBatchDestinationRevisions = statement{sqlite: `DELETE FROM destination_revisions WHERE (destination_id,revision) IN (SELECT destination_id,revision FROM destination_revisions WHERE created_at<? AND NOT EXISTS (SELECT 1 FROM destinations WHERE destinations.id=destination_id AND destinations.revision=destination_revisions.revision) AND NOT EXISTS (SELECT 1 FROM outbox WHERE outbox.destination_id=destination_revisions.destination_id AND outbox.destination_revision=destination_revisions.revision) ORDER BY created_at,destination_id,revision LIMIT ?)`, postgres: `DELETE FROM destination_revisions WHERE workspace_id=current_setting('ding.workspace') AND (destination_id,revision) IN (SELECT destination_id,revision FROM destination_revisions WHERE workspace_id=current_setting('ding.workspace') AND created_at<$1 AND NOT EXISTS (SELECT 1 FROM destinations WHERE workspace_id=current_setting('ding.workspace') AND destinations.id=destination_id AND destinations.revision=destination_revisions.revision) AND NOT EXISTS (SELECT 1 FROM outbox WHERE workspace_id=current_setting('ding.workspace') AND outbox.destination_id=destination_revisions.destination_id AND outbox.destination_revision=destination_revisions.revision) ORDER BY created_at,destination_id,revision LIMIT $2)`}
